"use client";
import { useTransition } from "react";

export default function SearchButton({ onSearch }) {
  const [pending, startTransition] = useTransition();
  return <button onClick={() => startTransition(() => onSearch())}>
    {pending ? "Searching..." : "Search"}
  </button>;
}

