import { cache } from 'react'

export const getUser = cache(async (id: string) => {
  return db.user.findUnique({ where: { id } })
})

export default async function Page() {
  const [a, b] = await Promise.all([getUser('1'), getUser('1')])
  return <div>{a?.name === b?.name ? 'same' : 'diff'}</div>
}

export default async function Page() {
  const userPromise = getUser()
  const statsPromise = getStats()
  const alertsPromise = getAlerts()

  const [user, stats, alerts] = await Promise.all([
    userPromise, statsPromise, alertsPromise
  ])
  return <Dashboard user={user} stats={stats} alerts={alerts} />
}

